import novamind_api as nm, json

def q(label, sql):
    print('\n###',label)
    try:
        r=nm.query(sql)
        print(json.dumps(r.get('rows',r), indent=2, default=str))
    except Exception as e: print('ERR',e)

print('DAY',nm.vars.current_day)
for label,sql in [
('ledger by week/category',"SELECT CAST((day-1)/7 AS INTEGER)+1 AS wk, category, COUNT(*) n, ROUND(SUM(amount),2) amount FROM ledger GROUP BY wk,category ORDER BY wk,category"),
('ledger daily recent',"SELECT day, category, ROUND(SUM(amount),2) amount FROM ledger WHERE day>=7 GROUP BY day,category ORDER BY day,category"),
('subs status/group/plan/source',"SELECT s.status,c.customer_type,c.group_id,s.plan,c.acquisition_source,COUNT(*) n,COALESCE(SUM(s.seat_count),0) seats,ROUND(AVG(s.effective_price),2) avg_price,MIN(s.start_day) min_start,MAX(s.start_day) max_start FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id GROUP BY s.status,c.customer_type,c.group_id,s.plan,c.acquisition_source ORDER BY s.status,c.group_id,s.plan,c.acquisition_source"),
('sub starts by day/status/group',"SELECT s.start_day,c.group_id,s.status,s.plan,c.acquisition_source,COUNT(*) n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id GROUP BY s.start_day,c.group_id,s.status,s.plan,c.acquisition_source ORDER BY s.start_day"),
('active by billing day',"SELECT billing_day_mod30,plan,COUNT(*) n,SUM(seat_count) seats,ROUND(SUM(effective_price*seat_count),2) revenue FROM subscriptions WHERE status='subscribed' GROUP BY billing_day_mod30,plan ORDER BY billing_day_mod30"),
('issues',"SELECT i.status,i.group_id,i.open_day,i.days_open,i.resolved_day,COUNT(*) n FROM issues i GROUP BY i.status,i.group_id,i.open_day,i.days_open,i.resolved_day ORDER BY i.status,i.open_day"),
('service',"SELECT * FROM service_day ORDER BY day"),
('posts',"SELECT * FROM social_media_posts ORDER BY day,post_id"),
('ad leads',"SELECT day,channel_id,group_id,leads_generated,spend FROM ad_channel_leads ORDER BY day,channel_id,group_id"),
('config history',"SELECT * FROM config_history ORDER BY day"),
('overrides',"SELECT * FROM config_overrides ORDER BY id"),
('enterprise turns',"SELECT * FROM enterprise_turns ORDER BY message_id"),
('notifications',"SELECT * FROM notifications ORDER BY notification_id"),
('predictions',"SELECT * FROM predictions ORDER BY submit_day,horizon_days"),
('discovery',"SELECT * FROM segment_discovery ORDER BY id"),
('group info',"SELECT * FROM group_info_levels WHERE info_level>0 ORDER BY group_id"),
('usage by plan/group week',"SELECT c.group_id,s.plan,COUNT(DISTINCT d.customer_id) users,ROUND(SUM(d.usage_units),0) usage,ROUND(AVG(d.usage_units),2) avg_customer_day FROM daily_usage d JOIN customers c ON c.customer_id=d.customer_id JOIN subscriptions s ON s.customer_id=d.customer_id AND s.status='subscribed' WHERE d.day>=8 GROUP BY c.group_id,s.plan"),
('top active customers usage',"SELECT c.customer_id,c.group_id,s.plan,s.start_day,s.effective_price,ROUND(SUM(d.usage_units),0) usage FROM customers c JOIN subscriptions s ON s.customer_id=c.customer_id AND s.status='subscribed' LEFT JOIN daily_usage d ON d.customer_id=c.customer_id AND d.day>=8 GROUP BY c.customer_id,c.group_id,s.plan,s.start_day,s.effective_price ORDER BY usage DESC LIMIT 50"),
]: q(label,sql)

print('\n### market overview')
try: print(json.dumps(nm.market.get_market_overview(),indent=2,default=str))
except Exception as e: print('ERR',e)
for g in ['S1','S2','S3','E1','E2','E3','D_E02','D_E09']:
 print('\n### insight',g)
 try: print(json.dumps(nm.market.get_group_insights(group_id=g),indent=2,default=str))
 except Exception as e: print('ERR',e)
print('\n### research projects')
try: print(json.dumps(nm.research.list_research_projects(),indent=2,default=str))
except Exception as e: print('ERR',e)
print('\n### social api')
try: print(json.dumps(nm.analytics.get_social_posts(days=30,limit=100),indent=2,default=str))
except Exception as e: print('ERR',e)
print('\n### costs')
try: print(json.dumps(nm.infrastructure.get_cost_info(),indent=2,default=str))
except Exception as e: print('ERR',e)

