arguments.content:
import novamind_api as nm, json

def do(label, fn):
    print('\n###',label)
    try: print(json.dumps(fn(), indent=2, default=str))
    except Exception as e: print('ERROR',type(e).__name__,str(e))

# Reliability at the documented efficient baseline; targeted quality investment only where
# economically viable paid plans can be built. Stop burn on already-adequate discovered enterprises.
do('daily spend ops baseline', lambda: nm.marketing.set_daily_spend(operations=500, development=0))
do('targeted development', lambda: nm.analytics.set_targeted_dev_spend(targeted_spend={'S1':1000,'S2':1000,'S3':1000}))
do('targeted enterprise acquisition test', lambda: nm.marketing.set_targeted_ad_spend(targeted_spend={
    'content_marketing': {'D_E02':500},
    'linkedin': {'D_E09':500}
}))
# Ensure no accidental extra targeted operations spend.
do('clear targeted ops', lambda: nm.analytics.set_targeted_ops_spend(by_group={},by_plan={},by_group_plan={},by_customer={}))
# Follow through on the promised incident review and acknowledge the two themes in current feedback.
do('social update', lambda: nm.marketing.post_social_media(content="Incident review: two brief disruptions exposed gaps in our updates. We’ve expanded reliability coverage and support monitoring. We also hear creators on usage limits and are reviewing plan capacity. Thanks for holding us accountable."))

