cat > /tmp/w8.py <<'PY'
import novamind_api as nm, json
queries={
'plan_mix':'''SELECT s.plan, COUNT(*) n, ROUND(AVG(s.effective_price),2) avg_price, ROUND(SUM(s.effective_price),2) mrr FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' AND c.customer_type='individual' GROUP BY s.plan''',
'group_plan':'''SELECT c.group_id, s.plan, COUNT(*) n, ROUND(AVG(s.effective_price),2) avg_price FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' GROUP BY c.group_id,s.plan ORDER BY c.group_id,s.plan''',
'new_mix':'''SELECT start_day, plan, COUNT(*) n, ROUND(AVG(effective_price),2) p FROM subscriptions WHERE start_day>=50 AND status='subscribed' GROUP BY start_day,plan ORDER BY start_day,plan''',
'status':'''SELECT status, COUNT(*) n FROM subscriptions GROUP BY status''',
'issues':'''SELECT open_day, days_open, COUNT(*) n FROM issues WHERE resolved_day IS NULL GROUP BY open_day,days_open ORDER BY open_day''',
'ad_leads':'''SELECT day, channel_id, group_id, leads, spend FROM ad_channel_leads WHERE day>=50 ORDER BY day''',
'created':'''SELECT created_day, customer_type, COUNT(*) n FROM customers WHERE created_day>=50 GROUP BY created_day,customer_type ORDER BY created_day''',
'old_cohorts':'''SELECT s.start_day, SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) subscribed, SUM(CASE WHEN s.status!='subscribed' THEN 1 ELSE 0 END) inactive, COUNT(*) total FROM subscriptions s WHERE s.start_day BETWEEN 15 AND 56 GROUP BY s.start_day ORDER BY s.start_day''',
'billing':'''SELECT billing_day_mod30, COUNT(*) n, ROUND(SUM(effective_price),0) billings FROM subscriptions WHERE status='subscribed' GROUP BY billing_day_mod30 ORDER BY billing_day_mod30''',
'usage_by_plan':'''SELECT s.plan, COUNT(*) n, ROUND(AVG(s.effective_price),2) p FROM subscriptions s WHERE s.status='subscribed' GROUP BY s.plan''',
'enterprise_pending':'''SELECT * FROM enterprise_turns WHERE closed=0 LIMIT 50''',
'issue_open_close':'''SELECT day, event_type, COUNT(*) n FROM customer_events WHERE day>=50 GROUP BY day,event_type ORDER BY day,event_type'''
}
for name,sql in queries.items():
 print('\n===',name,'===')
 try: print(*nm.query(sql)['rows'],sep='\n')
 except Exception as e: print('ERR',e)
for name,func in [('cost',nm.infrastructure.get_cost_info),('market',nm.market.get_market_overview),('posts',lambda:nm.analytics.get_social_posts(days=10,limit=100)),('projects',nm.research.list_research_projects)]:
 print('\n===',name,'===')
 try: print(json.dumps(func(),indent=2,default=str))
 except Exception as e: print('ERR',e)
PY
./novamind-operation python /tmp/w8.py

