./novamind-operation python-c "import novamind_api as nm
for q in [
'''SELECT c.created_day,c.group_id,COUNT(*) leads,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) subs,SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost,ROUND(AVG(CASE WHEN s.status='subscribed' THEN s.effective_price END),2) avgp FROM customers c JOIN subscriptions s ON s.customer_id=c.customer_id WHERE c.created_day>=43 GROUP BY c.created_day,c.group_id ORDER BY c.created_day,c.group_id''',
'''SELECT c.group_id,COUNT(*) leads,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) subs,SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost,ROUND(AVG(CASE WHEN s.status='subscribed' THEN s.effective_price END),2) avgp FROM customers c JOIN subscriptions s ON s.customer_id=c.customer_id WHERE c.created_day>=50 GROUP BY c.group_id ORDER BY leads DESC''',
'''SELECT c.group_id,c.acquisition_source,COUNT(*) n,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) subs FROM customers c JOIN subscriptions s ON s.customer_id=c.customer_id WHERE c.created_day>=50 GROUP BY c.group_id,c.acquisition_source ORDER BY c.group_id,n DESC'''
]:
 print('\n--');
 try: print(*nm.query(q)['rows'],sep='\n')
 except Exception as e: print('ERR',e)"

