import novamind_api as nm
rows=nm.query("SELECT billing_day_mod30,plan,COUNT(*) n,SUM(effective_price) rev FROM subscriptions WHERE status='subscribed' GROUP BY billing_day_mod30,plan")['rows']
modplan={(i,p):{'n':0,'rev':0} for i in range(30) for p in 'ABC'}
for r in rows: modplan[(r['billing_day_mod30'],r['plan'])]={'n':r['n'],'rev':r['rev']}
# exact compute last week by daily phase
us=nm.query("SELECT du.day,s.plan,SUM(du.usage_units) usage FROM daily_usage du JOIN subscriptions s ON s.customer_id=du.customer_id WHERE du.day BETWEEN 57 AND 63 GROUP BY du.day,s.plan")['rows']
phase={}
for d in range(57,64): phase[d%7]=sum(r['usage']*{'A':.0003,'B':.006,'C':.03}[r['plan']] for r in us if r['day']==d)
# scenarios monthly survival A,B,C; compute proportional aggregate survival derive weighted active
scens={'bad':(.82,.92,.94,80000,28000),'low':(.88,.96,.97,70000,10000),'point':(.94,.985,.99,60000,10000),'high':(.98,.995,.995,55000,10000),'best':(1,1,1,50000,10000)}
for name,(sa,sb,sc,ops,cap) in scens.items():
 surv={'A':sa,'B':sb,'C':sc}
 print('\n',name)
 for H in [7,28,84,182]:
  rev=0; compute=0
  occ={(m,p):0 for m in range(30) for p in 'ABC'}
  for t in range(64,64+H):
   m=t%30
   for p in 'ABC':
    k=occ[(m,p)]
    rev += modplan[(m,p)]['rev']*(surv[p]**k)
    occ[(m,p)]+=1
   # aggregate survival continuous approximate with subscriber weights .762,.233,.004
   af=.762*(sa**((t-63)/30))+.233*(sb**((t-63)/30))+.004*(sc**((t-63)/30))
   compute += phase[t%7]*af
  cost=H*(ops+cap)+compute
  print(H,round(1801377+rev-cost), 'rev',round(rev),'cost',round(cost))
