import json
rows=json.load(open('/tmp/cohorts.json'))
# aggregate all groups/active
active=[]
for r in rows:
 if r['status']=='subscribed':
  due=r['start_day']
  while due<=70:due+=30
  active.append([r['n'],r['plan'],r['p'],due,r['start_day']])

def run(ra=.95,rb=.99, lowerB=True):
 cs=[x.copy() for x in active]; cash=1341662.7; out={}
 for day in range(71,253):
  rev=0
  for c in cs:
   if c[3]==day:
    r=rb if c[1] in ('B','C') else ra
    if day==71 and c[1]=='A': r-=.08
    elif day==72 and c[1]=='A':r-=.03
    before=c[0];c[0]*=r;rev+=c[0]*c[2];c[3]+=30
  na=sum(c[0] for c in cs if c[1]=='A');nb=sum(c[0] for c in cs if c[1]=='B');nc=sum(c[0] for c in cs if c[1]=='C')
  # empirical usage avg 74/77/73; B tier2 after d77
  cpu=na*74*.0003+nb*77*(.002 if lowerB and day>77 else .006)+nc*73*.03
  cost=60000+10000+cpu+(45000 if day<=77 else 0)
  cash+=rev-cost
  if day in [77,98,154,252]:out[day]=(cash,rev,cost,na+nb+nc)
 return out
for ra,rb in [(.92,.985),(.94,.99),(.96,.995),(.97,.997)]:print(ra,rb,run(ra,rb))
