cat docs/api/analytics.json; echo '\n--- marketing docs ---'; cat docs/api/marketing.json; echo '\n--- infrastructure costs---'; ./novamind-operation python-c "import novamind_api as nm,json; print(json.dumps(nm.infrastructure.get_cost_info(),indent=2,default=str))"; echo '\n--- concise metrics---'; ./novamind-operation python-c "import novamind_api as nm,json
qs=[('active A price',\"SELECT plan,listed_price,effective_price,COUNT(*) n,MIN(start_day) mi,MAX(start_day) ma FROM subscriptions WHERE status='subscribed' GROUP BY plan,listed_price,effective_price ORDER BY plan,listed_price,effective_price\"),('new mix',\"SELECT c.created_day day,c.group_id,s.plan,COUNT(*) n,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) sub,SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost,ROUND(SUM(CASE WHEN s.status='subscribed' THEN s.effective_price ELSE 0 END),0) mrr FROM customers c JOIN subscriptions s ON c.customer_id=s.customer_id WHERE c.created_day>=77 GROUP BY c.created_day,c.group_id,s.plan ORDER BY day,c.group_id,s.plan\"),('plan by billing mod',\"SELECT billing_day_mod30 mod,plan,listed_price,COUNT(*) n,ROUND(SUM(effective_price),0) mrr FROM subscriptions WHERE status='subscribed' GROUP BY mod,plan,listed_price ORDER BY mod,plan,listed_price\"),('issues sum',\"SELECT SUM(CASE WHEN days_open>0 THEN 1 ELSE 0 END) old, SUM(CASE WHEN days_open=0 THEN 1 ELSE 0 END) today, MAX(days_open) oldest FROM issues WHERE status='open'\")]
for name,q in qs:
 print('##',name)
 for x in nm.query(q)['rows']: print(x)
print('## social recent')
r=nm.analytics.get_social_posts(days=7,limit=30)
for p in r.get('posts',r if isinstance(r,list) else []): print(p.get('post_id'),p.get('day'),p.get('content','')[:240].replace('\\n',' '))
"

