import novamind_api as nm
# Reply to every open enterprise lead with a margin-positive, group-tailored month-to-month offer.
r=nm.query("SELECT DISTINCT et.customer_id,c.group_id FROM enterprise_turns et JOIN customers c USING(customer_id) WHERE et.closed=0")
prices={'E1':('A',19.0),'E2':('B',59.0),'E3':('B',79.0),'D_E02':('B',69.0),'D_E09':('B',89.0)}
deals=[]
for x in r['rows']:
    p,price=prices[x['group_id']]
    deals.append([x['customer_id'],[[p,price]]])
print('enterprise deals',len(deals),nm.enterprise.send_enterprise_deal(deals=deals))
# Stop unproductive LinkedIn. Scale only proven, immediately cash-positive individual channel/group pairs.
print(nm.marketing.set_targeted_ad_spend(targeted_spend={
    'search_ads': {'D_S07': 8000.0, 'S3': 6000.0, 'S2': 4000.0},
    'social_media': {'D_S10': 4000.0}
}))
# Preserve launch service posture and product/pricing controls.
