import novamind_api as nm, json

def q(sql,title):
 print('\n###',title)
 try:
  r=nm.query(sql); print('cols',r.get('columns')); 
  for x in r['rows']: print(x)
  if r.get('warning'): print(r['warning'])
 except Exception as e: print('ERR',e)

q("SELECT day, category, ROUND(SUM(amount),2) amount, COUNT(*) n FROM ledger WHERE day>=120 GROUP BY day,category ORDER BY day,category","ledger daily")
q("SELECT category, ROUND(SUM(amount),2) amount FROM ledger WHERE day BETWEEN 120 AND 126 GROUP BY category ORDER BY category","ledger week")
q("SELECT c.group_id,s.plan,COUNT(*) n, SUM(s.seat_count) seats, ROUND(AVG(s.effective_price),2) avg_price, ROUND(SUM(s.effective_price*s.seat_count),2) mrr FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' GROUP BY c.group_id,s.plan ORDER BY c.group_id,s.plan","active subs")
q("SELECT c.group_id,c.acquisition_source,s.plan,COUNT(*) n,ROUND(SUM(s.effective_price),2) mrr FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' AND c.created_day>=120 GROUP BY c.group_id,c.acquisition_source,s.plan ORDER BY c.group_id,c.acquisition_source,s.plan","new active cohort")
q("SELECT c.created_day day,c.group_id,COUNT(*) leads,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) current_subs,SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost,SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END) cancelled FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.customer_type='small' AND c.created_day>=120 GROUP BY c.created_day,c.group_id ORDER BY c.created_day,c.group_id","small leads conversion")
q("SELECT day,channel_id,group_id,SUM(leads_generated) leads,ROUND(SUM(spend),2) spend,ROUND(SUM(spend)/NULLIF(SUM(leads_generated),0),2) cpl FROM ad_channel_leads WHERE day>=120 GROUP BY day,channel_id,group_id ORDER BY day,channel_id,group_id","ads daily")
q("SELECT channel_id,group_id,SUM(leads_generated) leads,ROUND(SUM(spend),2) spend,ROUND(SUM(spend)/NULLIF(SUM(leads_generated),0),2) cpl FROM ad_channel_leads WHERE day BETWEEN 120 AND 126 GROUP BY channel_id,group_id ORDER BY channel_id,group_id","ads week")
q("SELECT day,total_usage_units,p95_ms,ROUND(error_rate,5) err,downtime_minutes,capacity_tier,capacity_units FROM service_day WHERE day>=120 ORDER BY day","service")
q("SELECT i.group_id,i.open_day,i.days_open,COUNT(*) n FROM issues i JOIN subscriptions s USING(customer_id) WHERE i.status='open' AND s.status='subscribed' GROUP BY i.group_id,i.open_day,i.days_open ORDER BY i.days_open DESC,i.group_id","open issue ages active")
q("SELECT group_id, status, COUNT(*) n FROM issues WHERE open_day>=120 GROUP BY group_id,status ORDER BY group_id,status","issues opened week")
