import json,collections
x=json.load(open('week22_data.json'))
# aggregate cohorts d148-154 by source/group
for dims in [('group_id',),('acquisition_source',),('group_id','acquisition_source')]:
 a={}
 for r in x['cohorts']:
  if r['created_day']<148: continue
  k=tuple(r[d] for d in dims)
  z=a.setdefault(k,dict(leads=0,subs=0,cur=0,init=0))
  z['leads']+=r['leads']; z['subs']+=r['current_subs']; z['cur']+=r['current_mrr'];z['init']+=r['initial_mrr']
 print('\n',dims)
 for k,z in sorted(a.items(),key=lambda kv:-kv[1]['init']):
  print(k,z,'surv',round(z['subs']/z['leads'],3),'init/lead',round(z['init']/z['leads'],1),'cur/lead',round(z['cur']/z['leads'],1))
# ads this week agg
print('\nADS')
a={}
for r in x['ads']:
 if r['day']<148:continue
 k=(r['channel_id'],r['group_id']); z=a.setdefault(k,[0,0]);z[0]+=r['leads'];z[1]+=r['spend']
for k,(l,s) in a.items(): print(k,l,s,'cpl',s/l if l else None)
# active group
print('\nactive group')
a={}
for r in x['active_group']:
 z=a.setdefault(r['group_id'],[0,0]);z[0]+=r['n'];z[1]+=r['mrr']
for k,z in sorted(a.items(),key=lambda kv:-kv[1][1]):print(k,z)
# issues age
print('\nissues')
a=collections.Counter();ag=collections.Counter()
for r in x['issues']:
 a[(r['open_day'],r['days_open'])]+=r['n'];ag[(r['group_id'],r['days_open'])]+=r['n']
print('by age',collections.Counter({age:sum(v for (g,a2),v in ag.items() if a2==age) for age in set(a for g,a in ag)}))
print('by group')
for k,v in sorted(collections.Counter({g:sum(v for (g2,a),v in ag.items() if g2==g) for g,a in ag}).items(),key=lambda kv:-kv[1]):print(k,v)
# bill future weekly
print('\nfuture dues')
for r in x['billing_future_mod']:print(r)
# daily ledger net
print('\nledger daily')
a={}
for r in x['ledger_daily']:
 if r['day']>=148:
  z=a.setdefault(r['day'],collections.defaultdict(float));z[r['category']]+=r['amount']
for d,z in a.items():print(d,round(sum(z.values())),dict(z))
