import novamind_api as nm, json

def p(x): print(json.dumps(x,indent=2,default=str)[:30000])
print('research'); p(nm.research.list_research_projects())
print('cost'); p(nm.infrastructure.get_cost_info())
print('social'); p(nm.analytics.get_social_posts(days=14,limit=150))
for g in ['S1','S2','S3','D_S07','D_S09','D_S10','D_S01','D_S02','D_S03','D_S04','D_S05','D_S06','D_S08','E1','E2','E3']:
 print('\nINSIGHT',g)
 try: p(nm.market.get_group_insights(group_id=g))
 except Exception as e: print('ERR',e)
print('notifications agg')
r=nm.query("SELECT day,type,COUNT(*) n,MIN(message) sample FROM notifications WHERE day>=169 GROUP BY day,type ORDER BY day,type")
for x in r['rows']: print(x)
print('config recent')
r=nm.query("SELECT * FROM config_history WHERE day>=169 ORDER BY day")
for x in r['rows']: print(x)
PY
./novamind-operation python inspect182.py > inspect182.txt
wc -l inspect182.txt; grep -nE 'research|cost|social|INSIGHT|notifications agg|config recent|Compet|compet|launch|quality' inspect182.txt | head -n 220

